INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user9305-chem312', 'stk-user9305', 'CHEM 312', 'doc', '{"docs": [{"id": "stk-dr-f68545", "n": "Dr. Mazen Khaled", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "CHEM 312 (Physical Chemistry III) - Term 152 Lec\n\nالتحضير:\nما فيه تحضير، كنا 5 طلاب وما كان يحتاج ينادي بالاسم او حتى يمرر ورقة.\n\nطريقة الشرح:\nالشرح جيد جداً من نوتاته، لكن المادة صعبة جداً Quantum Mechanics ومهما كان الدكتور اللي يشرحها فاهم راح تبقى غامضة وصعبة.\n\nالكويزات:\nلا يوجد، بدلاً منها كان يوجد عرض مرئي مدته 25 دقيقة عن أحد شباتر المادة، والدكتور يحجر فيه حتى اني حسيت اني قاعد اناقش رسالة الدكتوراة حقتي.\n\nالمياجر:\n3 مياجر كتابية، كل ميجر 5 أسئلة، مسموح لك بإحضار الكتاب وأي ورقة تريدها.\n\nفي كل ميجر السؤالين الرابع والخامس مستواهن عالي.\n\nالفاينل:\nمتوسط.\n\nالصوت:\nواضح جداً.\n\nإضافات:\n- الدكتور متفهم ومبتسم.\n\n- ينهي المحاضرة في وقتها دائماً.\n\n- متعاون بشكل كبير جداً في مواعيد الإختبارات، ومتفهم اذا ناقشناه في التصحيح بعد كل ميجر.\n\n- يفعل كل ما بوسعه لمساعدة الطلاب بكل ما تعنيه الكلمة.\n\nالقريد النهائي:\nA", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1451566-chem312", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mazen-khaled/68545/33", "user": "user9305", "ts": 1465737303000, "tid": 68545, "pn": 33}}]}', 1465737303000, 1794774613, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
COMMIT;
